"command": "cat > pass3_fit.py <<'PY'\n# Pass 3 fit (after pass2_body): delete Hermit hood-base shards above the cowl, tuck the robe under the cowl,\n# lay the Monk pendant onto the fattened robe surface. Run after pass2_body (which restores originals).\nimport sys, importlib, json, bpy, bmesh\nSCRIPTS = r\"C:\\Projects\\tms-heim\\runs\\2026-09-29-cald-kitbash\\scripts\"\nif SCRIPTS not in sys.path: sys.path.insert(0, SCRIPTS)\nimport cald_lib as C; importlib.reload(C); K = C.K\nfrom mathutils import Vector\nfrom mathutils.bvhtree import BVHTree\nP = dict(shard_z=1.46, tuck=0.015, pend_off=0.006)\nP.update(globals().get(\"PP\", {}))\narm = bpy.data.objects[\"Armature_Male\"]; M = arm.matrix_world; Mi = M.inverted(); R = M.to_3x3()\nrobe = bpy.data.objects[\"Cald_Robe\"]; cowl = bpy.data.objects[\"Cald_Cowl\"]; pend = bpy.data.objects[\"Cald_Pendant\"]\nrep = {}\n# a) shards: robe faces above the cowl collar dominated by Neck/Head\ng = {x.index: x.name for x in robe.vertex_groups}\nbm = bmesh.new(); bm.from_mesh(robe.data); dl = bm.verts.layers.deform.active\ndef dom(v): return g[max(v[dl].items(), key=lambda q: q[1])[0]] if v[dl] else \"-\"\nkill = [f for f in bm.faces if (M @ f.calc_center_median()).z > P[\"shard_z\"] and sum(dom(v) in (\"Neck\", \"Head\") for v in f.verts) * 2 >= len(f.verts)]\nrep[\"shards\"] = len(kill)\nbmesh.ops.delete(bm, geom=kill, context='FACES')\nbmesh.ops.delete(bm, geom=[v for v in bm.verts if not v.link_faces], context='VERTS')\nbm.to_mesh(robe.data); bm.free(); robe.data.update()\n# b) robe under cowl: cast along the robe vertex normal; if the cowl is hit close by (either side), sit tuck below it\nbpy.context.view_layer.update()\nctree = K.world_bvh([cowl], M); n = 0\nfor v in robe.data.vertices:\n    w = M @ v.co\n    if w.z < 1.2: continue\n    nw = (R @ v.normal).normalized()\n    h = ctree.ray_cast(w - nw * 0.06, nw, 0.14)\n    if h[0] is None: continue\n    s = (w - h[0]).dot(nw)            # >0: robe vert is outside the cowl surface along its normal\n    if s > -P[\"tuck\"]:\n        v.co = Mi @ (h[0] - nw * P[\"tuck\"]); n += 1\nrobe.data.update(); rep[\"robe_tucked\"] = n\n# c) pendant relief onto the robe surface\nbpy.context.view_layer.update()\nrtree = K.world_bvh([robe], M); n = 0\nfor v in pend.data.vertices:\n    w = M @ v.co; p, nrm, i, d = rtree.find_nearest(w)\n    if p is None: continue\n    v.co = Mi @ (p + nrm * P[\"pend_off\"]); n += 1\npend.data.update(); rep[\"pend_snapped\"] = n\nbpy.context.view_layer.update()\nrtree = K.world_bvh([robe], M)\ndef inside(o):\n    c = 0\n    for v in o.data.vertices:\n        w = M @ v.co; p, nrm, i, d = rtree.find_nearest(w)\n        if p is not None and d < 0.1 and (w - p).dot(nrm) < -0.003: c += 1\n    return c\nrep[\"inside_robe\"] = {x: inside(bpy.data.objects[x]) for x in (\"Cald_Cowl\", \"Cald_Pendant\")}\nrep[\"robe_loops\"] = K.boundary_loops(robe)\nbpy.ops.wm.save_mainfile()\nresult = rep\nPY\npython bl.py pass2_body.py >/dev/null && python bl.py pass3_fit.py | head -40 && python bl.py -c \"TAG='p3'\nVIEWS=['front','threequarter','side','back','upper34']\n$(cat render_eevee.py)\" > /dev/null && python sheet.py p3 front threequarter side back upper34",
