"command": "mkdir -p /c/Projects/bws.iron-canopy/Assets/IronCanopy/Art/Shaders && cd /c/Projects/bws.iron-canopy/Assets/IronCanopy/Art/Shaders && cat > HB_LightShaft.shader <<'EOF'\n// In-house volumetric light shaft (G4-5): additive, unlit, no depth or opaque texture. Soft across the beam (uv.x),\n// fading toward its far end (uv.y), with slow drifting dust bands; fades with scene fog and close to the camera so\n// it never washes over the gameplay plane. Label: mobile-safe (a few quads; cost is overdraw, reviewed in G6).\nShader \"IronCanopy/HB Light Shaft\"\n{\n    Properties\n    {\n        [HDR] _Color (\"Color\", Color) = (1, 0.95, 0.85, 0.35)\n        _EdgeSoftness (\"Edge softness\", Range(0.5, 4)) = 1.6\n        _DustScale (\"Dust band scale\", Float) = 3\n        _DustSpeed (\"Dust drift speed\", Float) = 0.08\n        _NearFade (\"Near fade distance (m)\", Float) = 12\n    }\n    SubShader\n    {\n        Tags { \"RenderType\" = \"Transparent\" \"Queue\" = \"Transparent\" \"RenderPipeline\" = \"UniversalPipeline\" \"IgnoreProjector\" = \"True\" }\n        Pass\n        {\n            Name \"Shaft\"\n            Blend One One\n            ZWrite Off\n            Cull Off\n            HLSLPROGRAM\n            #pragma vertex vert\n            #pragma fragment frag\n            #pragma multi_compile_fog\n            #include \"Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl\"\n\n            CBUFFER_START(UnityPerMaterial)\n                half4 _Color;\n                half _EdgeSoftness, _DustScale, _DustSpeed, _NearFade;\n            CBUFFER_END\n\n            struct Attributes { float4 positionOS : POSITION; float2 uv : TEXCOORD0; };\n            struct Varyings { float4 positionCS : SV_POSITION; float2 uv : TEXCOORD0; float3 positionWS : TEXCOORD1; half fog : TEXCOORD2; };\n\n            Varyings vert(Attributes v)\n            {\n                Varyings o;\n                var_unused:;\n                o.positionWS = TransformObjectToWorld(v.positionOS.xyz);\n                o.positionCS = TransformWorldToHClip(o.positionWS);\n                o.uv = v.uv;\n                o.fog = ComputeFogFactor(o.positionCS.z);\n                return o;\n            }\n\n            half4 frag(Varyings i) : SV_Target\n            {\n                half across = pow(saturate(sin(i.uv.x * PI)), _EdgeSoftness);\n                half along = saturate(1.0 - i.uv.y) * saturate(i.uv.y * 6.0);\n                half dust = 0.75 + 0.25 * sin((i.uv.x * 2.3 + i.uv.y) * _DustScale * 6.2831 + _Time.y * _DustSpeed * 6.2831);\n                half near = saturate(distance(i.positionWS, GetCameraPositionWS()) / max(_NearFade, 0.01) - 0.5);\n                half a = _Color.a * across * along * dust * near;\n                half3 c = _Color.rgb * a;\n                c = MixFogColor(c, half3(0, 0, 0), i.fog);   // additive: fog fades the shaft out\n                return half4(c, 0);\n            }\n            ENDHLSL\n        }\n    }\n}\nEOF\nsed -i '/var_unused:;/d' HB_LightShaft.shader\ncat > HB_Creek.shader <<'EOF'\n// In-house creek water (G4-5): procedural ripple normals, Fresnel reflection of the creek's reflection probe\n// (mobile-safe: one probe rendered on load) and optional refraction of the opaque scene colour (_REFRACTION,\n// budget-review: needs the camera opaque texture). Decorative only: no collider, no swimming (SPEC \u00a713).\nShader \"IronCanopy/HB Creek\"\n{\n    Properties\n    {\n        _ShallowColor (\"Shallow colour\", Color) = (0.36, 0.45, 0.46, 0.55)\n        _DeepColor (\"Deep colour\", Color) = (0.12, 0.2, 0.24, 0.85)\n        _RippleScale (\"Ripple scale\", Float) = 1.3\n        _RippleSpeed (\"Ripple speed\", Float) = 0.35\n        _RippleStrength (\"Ripple strength\", Range(0, 1)) = 0.35\n        _ReflectionStrength (\"Reflection strength\", Range(0, 1)) = 0.8\n        _RefractionStrength (\"Refraction offset\", Range(0, 0.1)) = 0.025\n        _FresnelPower (\"Fresnel power\", Range(1, 8)) = 4\n    }\n    SubShader\n    {\n        Tags { \"RenderType\" = \"Transparent\" \"Queue\" = \"Transparent-10\" \"RenderPipeline\" = \"UniversalPipeline\" }\n        Pass\n        {\n            Name \"Creek\"\n            Tags { \"LightMode\" = \"UniversalForward\" }\n            Blend SrcAlpha OneMinusSrcAlpha\n            ZWrite Off\n            HLSLPROGRAM\n            #pragma vertex vert\n            #pragma fragment frag\n            #pragma multi_compile_fog\n            #pragma multi_compile _ _CLUSTER_LIGHT_LOOP\n            #pragma multi_compile_fragment _ _REFLECTION_PROBE_BLENDING\n            #pragma multi_compile_fragment _ _REFLECTION_PROBE_BOX_PROJECTION\n            #pragma shader_feature_local_fragment _ _REFRACTION\n            #define _SCREENSPACEREFLECTIONS_OFF 1\n            #include \"Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl\"\n            #include \"Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl\"\n            #include \"Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareOpaqueTexture.hlsl\"\n\n            CBUFFER_START(UnityPerMaterial)\n                half4 _ShallowColor, _DeepColor;\n                half _RippleScale, _RippleSpeed, _RippleStrength, _ReflectionStrength, _RefractionStrength, _FresnelPower;\n            CBUFFER_END\n\n            struct Attributes { float4 positionOS : POSITION; float3 normalOS : NORMAL; };\n            struct Varyings { float4 positionCS : SV_POSITION; float3 positionWS : TEXCOORD0; half fog : TEXCOORD1; };\n\n            Varyings vert(Attributes v)\n            {\n                Varyings o;\n                o.positionWS = TransformObjectToWorld(v.positionOS.xyz);\n                o.positionCS = TransformWorldToHClip(o.positionWS);\n                o.fog = ComputeFogFactor(o.positionCS.z);\n                return o;\n            }\n\n            // Two crossing sine swells, flowing downstream (+X): analytic slope gives the normal.\n            half3 RippleNormal(float2 p)\n            {\n                float t = _Time.y * _RippleSpeed;\n                float2 d1 = float2(0.8, 0.6), d2 = float2(-0.3, 0.95);\n                float a1 = dot(p, d1) * _RippleScale * 2.1 - t * 3.0;\n                float a2 = dot(p, d2) * _RippleScale * 3.7 - t * 2.1;\n                float2 slope = d1 * cos(a1) * 0.6 + d2 * cos(a2) * 0.4;\n                return normalize(half3(-slope.x * _RippleStrength, 1.0, -slope.y * _RippleStrength));\n            }\n\n            half4 frag(Varyings i) : SV_Target\n            {\n                half3 n = RippleNormal(i.positionWS.xz);\n                half3 v = normalize(GetWorldSpaceViewDir(i.positionWS));\n                half fresnel = pow(1.0 - saturate(dot(n, v)), _FresnelPower);\n                float2 screenUV = GetNormalizedScreenSpaceUV(i.positionCS);\n                half3 reflection = GlossyEnvironmentReflection(reflect(-v, n), i.positionWS, 0.08, 1.0, screenUV);\n\n                half depthMix = saturate(fresnel * 1.5);\n                half4 body = lerp(_ShallowColor, _DeepColor, depthMix);\n                half3 color = body.rgb;\n                half alpha = body.a;\n            #if defined(_REFRACTION)\n                half3 behind = SampleSceneColor(screenUV + n.xz * _RefractionStrength);\n                color = lerp(behind * _ShallowColor.rgb * 1.6, body.rgb, depthMix);\n                alpha = 1.0;\n            #endif\n                color = lerp(color, reflection, saturate(fresnel + 0.15) * _ReflectionStrength);\n                Light sun = GetMainLight();\n                half spec = pow(saturate(dot(n, normalize(sun.direction + v))), 180.0) * 2.0;\n                color += sun.color * spec;\n                color = MixFog(color, i.fog);\n                return half4(color, alpha);\n            }\n            ENDHLSL\n        }\n    }\n}\nEOF\necho ok",
